SELECT T2.`ID` as `id`, T2.NAME as `name`, T2.LINK as `link`, T2.ICON as `icon`,  T2.`PARENT_ID` as `parent`, T2.`IS_PARENT` as `is_parent`, T2.`SORT_ORDER` as `order`, T2.`STATUS` as status,(CASE WHEN  T1.VIEW_PER = 'Y' OR T1.ADD_PER = 'Y' OR T1.EDIT_PER = 'Y' OR T1.DEL_PER = 'Y' OR T1.PRINT_PER = 'Y' THEN 1 ELSE 0 END) as m_permission FROM `permission_master` as T1 INNER JOIN menu as T2 ON T2.ID = T1.ID where T1.DESIGNATION_ID = p_user_group_id AND PERMISSION_STATUS = 'Y' GROUP BY T2.ID HAVING m_permission > 0  ORDER BY `order` ASC;
