DELIMITER $$
CREATE TRIGGER `user_master_delete` AFTER DELETE ON `osh_user_master` FOR EACH ROW BEGIN

DELETE FROM osh_user_details WHERE user_master_id = OLD.id;
DELETE FROM osh_user_experience WHERE user_master_id = OLD.id;
DELETE FROM osh_user_vitals WHERE user_master_id = OLD.id;
DELETE FROM osh_user_health WHERE user_master_id = OLD.id;
DELETE FROM osh_user_insurance WHERE user_master_id = OLD.id;
END
$$
DELIMITER ;

